const target = $('Fetch Target Item').item.json[0];
const candidates = $json;
const matches = [];

for (const cand of candidates) {
  let score = 0;
  const details = {};

  // 1. Category Match (+30)
  if (target.ai_category && cand.ai_category && target.ai_category.toLowerCase() === cand.ai_category.toLowerCase()) {
    score += 30;
    details.category = { match: true, score: 30 };
  }

  // 2. Tag Overlap - Jaccard Index (+40)
  const targetTags = new Set(target.ai_tags || []);
  const candTags = new Set(cand.ai_tags || []);
  const overlap = [...targetTags].filter(t => candTags.has(t));
  const totalUnique = new Set([...targetTags, ...candTags]);
  if (totalUnique.size > 0) {
    const jaccard = overlap.length / totalUnique.size;
    const tagScore = Math.round(jaccard * 40);
    score += tagScore;
    details.tags = { overlap, score: tagScore };
  }

  // 3. Location Proximity (+20)
  if (target.location_building && cand.location_building && target.location_building.trim() === cand.location_building.trim()) {
    score += 20;
    details.location = { match: true, score: 20 };
  }

  // 4. Time Window (+10 if within 14 days)
  const tDate = new Date(target.event_date || target.created_at);
  const cDate = new Date(cand.event_date || cand.created_at);
  const diffDays = Math.abs(tDate - cDate) / (1000 * 60 * 60 * 24);
  if (diffDays <= 14) {
    score += 10;
    details.time = { diffDays: Math.round(diffDays), score: 10 };
  }

  if (score >= 60) {
    const lostId = target.type === 'LOST' ? target.id : cand.id;
    const foundId = target.type === 'FOUND' ? target.id : cand.id;
    matches.push({
      lost_item_id: lostId,
      found_item_id: foundId,
      score,
      match_details: details,
      is_high_match: score >= 75
    });
  }
}

return matches.map(m => ({ json: m }));
